from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
graph=json.loads((ROOT/"kg/graph.json").read_text(encoding="utf-8"))
data=json.dumps(graph,ensure_ascii=False,separators=(",",":")).replace("<","\\u003c")
page=r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>固态电解质知识图谱</title>
<style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#fff;color:#202328;font-family:system-ui,"Microsoft YaHei",sans-serif}body{display:flex;flex-direction:column}
header{display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:10px 15px;background:#fff;border-bottom:1px solid #e5e7eb;box-shadow:0 1px 4px #00000008}
h1{font-size:17px;font-weight:620;margin:0 10px 0 0;color:#202328}input,select,button{font:inherit;color:#30343a;background:white;border:1px solid #d5d8dc;border-radius:6px;padding:7px 10px}input{min-width:210px}button{cursor:pointer}button:hover{background:#f3f4f6;border-color:#8a8f96}
#count{margin-left:auto;color:#73777e;font-size:12px}main{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 300px}#stage{position:relative;min-width:0;min-height:0;overflow:hidden;background:#fff}canvas{display:block;width:100%;height:100%;cursor:grab}canvas.drag{cursor:grabbing}
aside{padding:14px;background:#fff;border-left:1px solid #e5e7eb;overflow:auto}aside h2{font-size:15px;margin:0 0 12px;color:#333}#info{font-size:13px;line-height:1.55;color:#555;overflow-wrap:anywhere}
.hint{position:absolute;left:12px;bottom:12px;background:#fffffff0;border:1px solid #e5e7eb;border-radius:6px;padding:7px 10px;color:#70757d;font-size:12px;pointer-events:none}.name{font-size:16px;font-weight:650;color:#202328;margin:8px 0}
.badge{display:inline-block;padding:2px 8px;border-radius:20px;background:#f0f1f2;color:#4c5055;font-size:11px}.rel{border-top:1px solid #eceef0;padding:8px 0;color:#42464b}.kv{margin:5px 0;color:#62676d}
@media(max-width:760px){main{grid-template-columns:1fr;grid-template-rows:minmax(0,1fr) 220px}aside{border:0;border-top:1px solid #e5e7eb}#count{margin-left:0}header{gap:7px}h1{width:100%}}
</style></head><body><header><h1>固态电解质知识图谱</h1><input id="search" placeholder="搜索材料、元素或性能"><select id="kind"><option value="">全部实体类型</option></select><button id="fit">适应画布</button><button id="reset">重置布局</button><span id="count"></span></header>
<main><section id="stage"><canvas id="canvas"></canvas><div class="hint">拖动节点 · 拖动空白处平移 · 滚轮缩放 · 鼠标扫过时节点与连线轻柔跟随 · 点击节点查看详情</div></section><aside><h2>节点信息</h2><div id="info">选择图中节点查看详细信息。</div></aside></main>
<script>
const G=__DATA__,golden=Math.PI*(3-Math.sqrt(5));
const shades={Paper:"#737980",Electrolyte:"#202328",Element:"#4d535a",Dopant:"#383d43",SynthesisMethod:"#686e75",Performance:"#444a50",Stability:"#25292e"};
function makeNodes(){return G.nodes.map((d,i)=>{let r=27*Math.sqrt(i+1),a=i*golden;return Object.assign({},d,{x:Math.cos(a)*r,y:Math.sin(a)*r,depth:Math.sin(i*1.73),phase:i*2.399,amp:.7+(i%5)*.16,r:d.type==="Electrolyte"?8:6})})}
const nodes=makeNodes(),byId=new Map(nodes.map(n=>[n.id,n])),edges=G.edges.filter(e=>byId.has(e.source)&&byId.has(e.target)),stage=document.getElementById("stage"),canvas=document.getElementById("canvas"),ctx=canvas.getContext("2d"),filter=document.getElementById("kind"),search=document.getElementById("search"),info=document.getElementById("info");
[...new Set(nodes.map(n=>n.type))].sort().forEach(t=>{let o=document.createElement("option");o.value=t;o.textContent=t;filter.append(o)});document.getElementById("count").textContent=nodes.length+" 个实体 · "+edges.length+" 条关系";
let W=1,H=1,D=1,zoom=1,ox=0,oy=0,selected=null,hover=null,selectedAt=0,drag=null,pan=null,cursor={x:-10000,y:-10000,tx:-10000,ty:-10000,power:0,active:false};
function visible(n){return(!filter.value||n.type===filter.value)&&(!search.value||(n.name+" "+(n.formula||"")).toLowerCase().includes(search.value.toLowerCase()))}
function base(n){let d=1+n.depth*.045;return{x:ox+n.x*zoom*d,y:oy+n.y*zoom*d}}
function waveOffset(p,now){let dx=p.x-cursor.x,dy=p.y-cursor.y,d=Math.hypot(dx,dy)||1,fall=Math.exp(-(d*d)/(2*82*82)),strength=4.0*fall*cursor.power;return{x:dx/d*strength,y:dy/d*strength}}
function motionOffset(n,now){let t=now*.001;return{x:Math.sin(t*.72+n.phase)*n.amp,y:Math.cos(t*.61+n.phase*1.17)*n.amp*.8}}
function point(n,now){let p=base(n),m=motionOffset(n,now);p.x+=m.x;p.y+=m.y;let o=waveOffset(p,now);return{x:p.x+o.x,y:p.y+o.y}}
function fitView(only){let a=only?nodes.filter(visible):nodes;if(!a.length)return;let x0=Infinity,x1=-Infinity,y0=Infinity,y1=-Infinity;for(let n of a){x0=Math.min(x0,n.x-n.r);x1=Math.max(x1,n.x+n.r);y0=Math.min(y0,n.y-n.r);y1=Math.max(y1,n.y+n.r)}let pad=55;zoom=Math.max(.12,Math.min(2.2,(W-2*pad)/(x1-x0||1),(H-2*pad)/(y1-y0||1)));ox=W/2-(x0+x1)*zoom/2;oy=H/2-(y0+y1)*zoom/2}
function resize(){let r=stage.getBoundingClientRect();W=r.width;H=r.height;D=devicePixelRatio||1;canvas.width=Math.max(1,Math.round(W*D));canvas.height=Math.max(1,Math.round(H*D));ctx.setTransform(D,0,0,D,0,0);fitView(false)}new ResizeObserver(resize).observe(stage);
function draw(){const now=performance.now(),breath=1+.018*Math.sin(now*.00072);cursor.x+=(cursor.tx-cursor.x)*.16;cursor.y+=(cursor.ty-cursor.y)*.16;cursor.power+=((cursor.active?1:0)-cursor.power)*.09;ctx.clearRect(0,0,W,H);ctx.fillStyle="#fff";ctx.fillRect(0,0,W,H);
 const shown=nodes.filter(visible),ids=new Set(shown.map(n=>n.id)),pos=new Map(),linked=new Set();for(let n of shown)pos.set(n.id,point(n,now));if(selected)for(let e of edges){if(e.source===selected.id)linked.add(e.target);else if(e.target===selected.id)linked.add(e.source)}
 for(let e of edges){if(!ids.has(e.source)||!ids.has(e.target))continue;let a=pos.get(e.source),b=pos.get(e.target),hot=selected&&(e.source===selected.id||e.target===selected.id);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=hot?"#34383d":"#bfc3c7";ctx.globalAlpha=hot?1:.72+.07*Math.sin(now*.00072);ctx.lineWidth=hot?1.45:.8;ctx.stroke();ctx.globalAlpha=1}
 for(let n of shown){let p=pos.get(n.id),r=Math.max(2.6,n.r*zoom*(1+n.depth*.1)*breath);ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=shades[n.type]||"#444";ctx.shadowColor="rgba(25,29,34,.20)";ctx.shadowBlur=7*breath;ctx.shadowOffsetX=0;ctx.shadowOffsetY=1.5*breath;ctx.fill();ctx.shadowColor="transparent";ctx.shadowBlur=0;ctx.shadowOffsetY=0;if(n===selected||n===hover){ctx.beginPath();ctx.arc(p.x,p.y,r+4,0,Math.PI*2);ctx.strokeStyle=n===selected?"#202328":"#858b92";ctx.lineWidth=1;ctx.stroke()}if(n===selected||linked.has(n.id)||n===hover||(search.value&&shown.length<35)){let isSel=n===selected,isLinked=linked.has(n.id),fs=isSel?18:isLinked?12:n===hover?13:10,label=n.name.slice(0,42);ctx.save();ctx.globalAlpha=isSel?Math.min(1,(now-selectedAt)/140):1;ctx.font=(isSel?"700 ":isLinked?"550 ":"500 ")+fs+"px system-ui";ctx.textBaseline="middle";let lx=p.x+r+(isSel?9:5),ly=p.y;if(isSel){let tw=ctx.measureText(label).width;ctx.fillStyle="rgba(255,255,255,.96)";ctx.fillRect(lx-5,ly-fs*.78,tw+10,fs*1.55);ctx.strokeStyle="#555b61";ctx.lineWidth=.8;ctx.strokeRect(lx-5,ly-fs*.78,tw+10,fs*1.55)}ctx.fillStyle=isSel?"#17191c":isLinked?"#575c62":"#30343a";ctx.fillText(label,lx,ly);ctx.restore()}}

 requestAnimationFrame(draw)}
function hit(x,y,now){for(let i=nodes.length-1;i>=0;i--){let n=nodes[i];if(!visible(n))continue;let p=point(n,now),r=Math.max(10,n.r*zoom*1.5);if((x-p.x)**2+(y-p.y)**2<r*r)return n}return null}
function inspect(n){selected=n;selectedAt=performance.now();if(!n){info.textContent="选择图中节点查看详细信息。";return}info.replaceChildren();let t=document.createElement("div");t.className="name";t.textContent=n.name;info.append(t);let b=document.createElement("span");b.className="badge";b.textContent=n.type;info.append(b);for(let[k,v]of Object.entries(n))if(!["id","type","name","x","y","depth","phase","amp","r"].includes(k)&&v!=null&&v!==""){let d=document.createElement("div");d.className="kv";d.textContent=k+": "+(typeof v==="object"?JSON.stringify(v):v);info.append(d)}let rels=edges.filter(e=>e.source===n.id||e.target===n.id),h=document.createElement("h3");h.textContent="关联关系（"+rels.length+"）";info.append(h);for(let e of rels){let o=byId.get(e.source===n.id?e.target:e.source),d=document.createElement("div");d.className="rel";d.textContent=(e.source===n.id?"→ ":"← ")+e.relation+" · "+(o?o.name:e.target)+(e.paper_id?" · "+e.paper_id:"");info.append(d)}}
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);let n=hit(e.offsetX,e.offsetY,performance.now());if(n){let p=point(n,performance.now());drag={n,dx:e.offsetX-p.x,dy:e.offsetY-p.y};inspect(n)}else pan={x:e.offsetX,y:e.offsetY,ox,oy}};
canvas.onpointermove=e=>{let now=performance.now();if(drag){let n=drag.n,d=1+n.depth*.045,bias=waveOffset(base(n),now),idle=motionOffset(n,now);n.x=(e.offsetX-drag.dx-bias.x-idle.x-ox)/(zoom*d);n.y=(e.offsetY-drag.dy-bias.y-idle.y-oy)/(zoom*d);n.x=Math.max(-900,Math.min(900,n.x));n.y=Math.max(-900,Math.min(900,n.y))}else if(pan){ox=pan.ox+e.offsetX-pan.x;oy=pan.oy+e.offsetY-pan.y}else{cursor.tx=e.offsetX;cursor.ty=e.offsetY;cursor.active=true;hover=hit(e.offsetX,e.offsetY,now)}canvas.classList.toggle("drag",!!drag||!!pan)};
canvas.onpointerup=()=>{drag=null;pan=null;canvas.classList.remove("drag")};canvas.onpointerleave=()=>{hover=null;cursor.active=false};
canvas.onwheel=e=>{e.preventDefault();let old=zoom;zoom=Math.max(.12,Math.min(4,zoom*(e.deltaY<0?1.12:.89)));ox=e.offsetX-(e.offsetX-ox)*zoom/old;oy=e.offsetY-(e.offsetY-oy)*zoom/old};
document.getElementById("fit").onclick=()=>fitView(true);document.getElementById("reset").onclick=()=>{nodes.splice(0,nodes.length,...makeNodes());byId.clear();nodes.forEach(n=>byId.set(n.id,n));cursor.active=false;cursor.power=0;inspect(null);fitView(false)};filter.onchange=()=>fitView(true);let timer;search.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>fitView(true),180)};
resize();fitView(false);draw();
</script></body></html>"""
(ROOT/"kg/knowledge_graph_interactive.html").write_text(page.replace("__DATA__",data),encoding="utf-8")
print("Generated grayscale interactive graph:",len(graph["nodes"]),"entities,",len(graph["edges"]),"relations")
